<?php                                                                                                                                                                                                                                                           
        App::uses('AppModel', 'Model');                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                                        
        class ApiKey extends AppModel {                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                                        
            public $name = 'ApiKey';                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                        
            public $validate = array(                                                                                                                                                                                                                                   
                'user_id' => array(                                                                                                                                                                                                                                     
                    'numeric' => array(                                                                                                                                                                                                                                 
                        'rule' => array('numeric'),                                                                                                                                                                                                                     
                        'message' => 'Please provide a valid user ID.',                                                                                                                                                                                                 
                    ),                                                                                                                                                                                                                                                  
                ),                                                                                                                                                                                                                                                      
                'client_name' => array(                                                                                                                                                                                                                                 
                    'notEmpty' => array(                                                                                                                                                                                                                                
                        'rule' => array('notEmpty'),                                                                                                                                                                                                                    
                        'message' => 'Please specify the client or application name.',                                                                                                                                                                                  
                    ),                                                                                                                                                                                                                                                  
                ),                                                                                                                                                                                                                                                      
                'api_key_hash' => array(                                                                                                                                                                                                                                
                    'notEmpty' => array(                                                                                                                                                                                                                                
                        'rule' => array('notEmpty'),                                                                                                                                                                                                                    
                        'message' => 'API Key hash cannot be empty.',                                                                                                                                                                                                   
                    ),                                                                                                                                                                                                                                                  
                ),                                                                                                                                                                                                                                                      
            );                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                                        
            public $belongsTo = array(                                                                                                                                                                                                                                  
                'User' => array(                                                                                                                                                                                                                                        
                    'className' => 'User',                                                                                                                                                                                                                              
                    'foreignKey' => 'user_id',                                                                                                                                                                                                                          
                )                                                                                                                                                                                                                                                       
            );                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                                        
            public function generateKey() {                                                                                                                                                                                                                             
                $rawBytes = openssl_random_pseudo_bytes(24);                                                                                                                                                                                                            
                $key = 'hatua_' . bin2hex($rawBytes);                                                                                                                                                                                                                   
                $prefix = substr($key, 0, 14);                                                                                                                                                                                                                          
                $hash = hash('sha256', $key);                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                                        
                return array(                                                                                                                                                                                                                                           
                    'key' => $key,                                                                                                                                                                                                                                      
                    'prefix' => $prefix,                                                                                                                                                                                                                                
                    'hash' => $hash                                                                                                                                                                                                                                     
                );                                                                                                                                                                                                                                                      
            }                                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                                        
            public function isIpAllowed($clientIp, $whitelist) {                                                                                                                                                                                                        
                $whitelist = trim((string)$whitelist);                                                                                                                                                                                                                  
                if ($whitelist === '') {                                                                                                                                                                                                                                
                    return true;                                                                                                                                                                                                                                        
                }                                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                                        
                $allowedEntries = array_filter(array_map('trim', explode(',', $whitelist)));                                                                                                                                                                            
                foreach ($allowedEntries as $entry) {                                                                                                                                                                                                                   
                    if ($entry === $clientIp) {                                                                                                                                                                                                                         
                        return true;                                                                                                                                                                                                                                    
                    }                                                                                                                                                                                                                                                   
                    if (strpos($entry, '/') !== false) {                                                                                                                                                                                                                
                        list($subnet, $bits) = explode('/', $entry, 2);                                                                                                                                                                                                 
                        if (filter_var($subnet, FILTER_VALIDATE_IP, FILTER_FLAG_IPV4) && is_numeric($bits)) {                                                                                                                                                           
                            $ipLong = ip2long($clientIp);                                                                                                                                                                                                               
                            $subnetLong = ip2long($subnet);                                                                                                                                                                                                             
                            $mask = -1 << (32 - (int)$bits);                                                                                                                                                                                                            
                            $subnetMasked = $subnetLong & $mask;                                                                                                                                                                                                        
                            if (($ipLong & $mask) === $subnetMasked) {                                                                                                                                                                                                  
                                return true;                                                                                                                                                                                                                            
                            }                                                                                                                                                                                                                                           
                        }                                                                                                                                                                                                                                               
                    }                                                                                                                                                                                                                                                   
                }                                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                                        
                return false;                                                                                                                                                                                                                                           
            }                                                                                                                                                                                                                                                           
        }                                                        